// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        vm.assume(nonAdmin != address(this));
        vm.assume(nonAdmin != msg.sender);
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
